frappe.ready(function () {
  const wf = frappe.web_form;
  const has = (f) => wf.fields_dict && wf.fields_dict[f];

  // 1. Fill name, mobile and email from the signed-in account (the citizen can still edit them)
  frappe.call({ method: "hasiruratha.citizen_api.my_profile", type: "GET" }).then((r) => {
    const p = r.message || {};
    ["full_name", "mobile", "email"].forEach((f) => {
      if (p[f] && has(f) && !wf.get_value(f)) wf.set_value(f, p[f]);
    });
  });

  // 2. Pin code must be 6 digits
  if (has("pincode")) {
    wf.on("pincode", (field, value) => {
      if (value && !/^\d{6}$/.test(String(value).trim())) {
        frappe.show_alert({ message: __("Pin code must be 6 digits"), indicator: "orange" });
      }
    });
  }

  // 3. "Send code to my email" button under the verification code field
  const wrap = document.querySelector('.frappe-control[data-fieldname="verification_code"]');
  if (!wrap || document.getElementById("hr-send-code")) return;
  wrap.insertAdjacentHTML(
    "afterend",
    '<div style="margin:-6px 0 12px"><button type="button" class="btn btn-default btn-sm" id="hr-send-code">' +
      __("Send code to my email") + "</button></div>"
  );
  const btn = document.getElementById("hr-send-code");
  btn.onclick = function () {
    const email = (wf.get_value("email") || "").trim();
    if (!email) {
      frappe.msgprint(__("Please enter your email first."));
      return;
    }
    btn.disabled = true;
    frappe
      .call({ method: "hasiruratha.citizen_api.send_email_code", type: "POST", args: { email: email } })
      .then(() => {
        frappe.msgprint(__("We sent a 6-digit code to your email. Enter it below."));
        let left = 60;
        const t = setInterval(() => {
          btn.textContent = __("Resend in {0}s", [left--]);
          if (left < 0) {
            clearInterval(t);
            btn.textContent = __("Send code to my email");
            btn.disabled = false;
          }
        }, 1000);
      })
      .catch(() => {
        btn.disabled = false; // the server message is already shown by frappe.call
      });
  };
});
